// EAU-Calibrated Deterministic Generator to add 100 cases (PT-1301 to PT-1400) for a 400-patient cohort
(function generateAdditionalCohort() {
  const locs = [
    { loc: "uvj", label: "UVJ (Ureterovesical Junction)", passProb: 0.85 },
    { loc: "distal", label: "Distal (Lower) Ureter", passProb: 0.70 },
    { loc: "mid", label: "Mid Ureter (Iliac Crossing)", passProb: 0.45 },
    { loc: "proximal", label: "Proximal (Upper) Ureter", passProb: 0.35 },
    { loc: "puj", label: "Pelviureteric Junction (PUJ)", passProb: 0.20 }
  ];

  // Seeded deterministic pseudo-random generator
  function seededRand(seed) {
    const x = Math.sin(seed) * 10000;
    return x - Math.floor(x);
  }

  for (let i = 1301; i <= 1400; i++) {
    const r1 = seededRand(i * 1.13);
    const r2 = seededRand(i * 2.37);
    const r3 = seededRand(i * 3.71);
    const r4 = seededRand(i * 4.93);
    const r5 = seededRand(i * 5.17);
    const r6 = seededRand(i * 6.43);

    const locObj = locs[Math.floor(r1 * locs.length)];
    const isLarge = r2 < 0.26; // ~26% > 7mm
    const size = isLarge ? +(7.1 + r3 * 4.4).toFixed(1) : +(2.1 + r3 * 4.8).toFixed(1);
    
    // EAU Rule: Size heavily modifies probability
    let sizeMod = 1.0;
    if (size > 7.0) sizeMod = 0.15; // Large stones rarely pass spontaneously
    else if (size <= 4.0) sizeMod = 1.35; // Small stones almost always pass
    
    // EAU Rule: HU influences density and intervention success
    const huValue = isLarge ? Math.floor(920 + r4 * 520) : Math.floor(380 + r4 * 650);
    let huCategory = huValue < 450 ? "Uric Acid" : huValue < 850 ? "Calcium Oxalate Dihydrate" : "Calcium Oxalate Monohydrate / Phosphate";
    
    // EAU Rule: MET (Medical Expulsive Therapy) works best on distal/UVJ
    const met = r5 > 0.28; // ~72% chance of MET
    let metMod = met && (locObj.loc === "distal" || locObj.loc === "uvj") ? 1.25 : 1.0;

    let finalPassProb = Math.min(0.95, locObj.passProb * sizeMod * metMod);
    
    const willPass = r6 < finalPassProb;
    const outcome = willPass ? "passed" : "intervention";
    const daysToPass = willPass ? Math.floor(2 + r2 * 24) : null;
    let intervention = "none";
    if (!willPass) {
      if (size >= 10 || locObj.loc === "puj") intervention = "urs";
      else intervention = r4 > 0.45 ? "swl" : "urs";
    }

    const hydronephrosis = size > 6 ? (size > 9 ? "severe" : "moderate") : "mild";
    const fever = false;
    const tlc = +(5.8 + r5 * 4.8).toFixed(1);
    
    // Calibrated Serum Creatinine
    let sCrBase = r3 > 0.5 ? 0.96 : 0.84;
    if (hydronephrosis === "moderate") sCrBase += 0.25;
    if (hydronephrosis === "severe") sCrBase += 0.65;
    if (outcome === "intervention" && size > 8) sCrBase += 0.30;
    const sCr = +(sCrBase + (r1 - 0.5) * 0.18).toFixed(2);
    
    window.INITIAL_PATIENT_COHORT_400.push({
      id: "PT-" + i,
      age: Math.floor(24 + r1 * 52),
      sex: r2 > 0.4 ? "M" : "F",
      stoneSizeMm: size,
      location: locObj.loc,
      locationLabel: locObj.label,
      huValue: huValue,
      huCategory: huCategory,
      painVas: Math.floor(4 + r3 * 6),
      durationDays: Math.floor(1 + r4 * 12),
      hydronephrosis: hydronephrosis,
      grossHematuria: r5 > 0.45,
      fever: fever,
      tlcCount: tlc,
      wbcCount: tlc,
      serumCreatinine: sCr,
      metPrescribed: met,
      outcome: outcome,
      daysToPassage: daysToPass,
      interventionType: intervention,
      notes: willPass ? `Uncomplicated spontaneous expulsion on day ${daysToPass}. Strainer positive.` : `Failed conservative surveillance. Required endourological removal (${intervention.toUpperCase()}).`
    });
  }

  // Ensure all 400 patient records contain explicit clinical TLC and Serum Creatinine values
  window.INITIAL_PATIENT_COHORT_400.forEach(p => {
    if (p.tlcCount === undefined) {
      p.tlcCount = p.wbcCount !== undefined ? p.wbcCount : +(6.2 + (p.fever ? 9.5 : 0) + (p.painVas > 7 ? 2.1 : 0)).toFixed(1);
    }
    if (p.wbcCount === undefined) {
      p.wbcCount = p.tlcCount;
    }
    if (p.serumCreatinine === undefined) {
      let baseline = p.sex === "M" ? 0.95 : 0.82;
      if (p.hydronephrosis === "moderate") baseline += 0.28;
      if (p.hydronephrosis === "severe") baseline += 0.68;
      if (p.fever) baseline += 0.45;
      if (p.outcome === "intervention" && p.stoneSizeMm > 8.0) baseline += 0.35;
      const numId = parseInt(p.id.replace(/\D/g, "") || "1", 10);
      const offset = (((numId * 17) % 25) - 12) / 100;
      p.serumCreatinine = +(Math.max(0.65, Math.min(2.80, baseline + offset))).toFixed(2);
    }
  });

  window.INITIAL_PATIENT_COHORT = window.INITIAL_PATIENT_COHORT_400;
})();
